14	// gfx_v2 on-device SIMT software fallback.
15	//
16	// The always-correct path that runs on the SIMT cores when a fixed-function
17	// unit cannot represent a required feature — full residency forbids a host
18	// (llvmpipe) fallback, so the completeness path lives on the device. This
19	// header is the device-compilable `libgfx_sw`; it is ALSO included by the host
20	// FF models (sw/common/gfx_ff_model.cpp) so the per-fragment math has a single
21	// source of truth — the SW path matches the FF
22	// path bit-for-bit because it IS the same code.
23	//
24	// First component: the software output-merger — depth/stencil test,
25	// blend, logic-op, write-mask — replacing the vx_om fixed-function call site.
26	// Freestanding (no <algorithm>/<cmath>) so it compiles for the baremetal device.
27	
28	#pragma once
29	
30	#include <stdint.h>
31	#include <VX_types.h>
32	#include "gfx_frag_tex.h"   // shared tex-sampling math (FF model + SW path)
33	#include <cocogfx/include/color.hpp>
34	#include <cocogfx/include/math.hpp>
35	
36	namespace gfx_sw {
37	
38	using cocogfx::ColorARGB;
39	using cocogfx::Div255;
40	
41	// Local min/max so the header stays freestanding (device baremetal has no
42	// <algorithm>); identical results to std::min/std::max for the integer use here.
43	template <typename T> static inline __attribute__((always_inline)) T sw_min(T a, T b) { return a < b ? a : b; }
44	template <typename T> static inline __attribute__((always_inline)) T sw_max(T a, T b) { return a > b ? a : b; }
45	
46	// ── Pure per-fragment ops (single source of truth for FF model + SW path) ────
47	
48	static inline __attribute__((always_inline)) bool DoCompare(uint32_t func, uint32_t a, uint32_t b) {
49	  switch (func) {
50	  case VX_OM_DEPTH_FUNC_NEVER:    return false;
51	  case VX_OM_DEPTH_FUNC_LESS:     return (a < b);
52	  case VX_OM_DEPTH_FUNC_EQUAL:    return (a == b);
53	  case VX_OM_DEPTH_FUNC_LEQUAL:   return (a <= b);
54	  case VX_OM_DEPTH_FUNC_GREATER:  return (a > b);
55	  case VX_OM_DEPTH_FUNC_NOTEQUAL: return (a != b);
56	  case VX_OM_DEPTH_FUNC_GEQUAL:   return (a >= b);
57	  case VX_OM_DEPTH_FUNC_ALWAYS:   default: return true;
58	  }
59	}
60	
61	static inline __attribute__((always_inline)) uint32_t DoStencilOp(uint32_t op, uint32_t ref, uint32_t val) {
62	  switch (op) {
63	  case VX_OM_STENCIL_OP_ZERO:      return 0;
64	  case VX_OM_STENCIL_OP_REPLACE:   return ref;
65	  case VX_OM_STENCIL_OP_INCR:      return (val < 0xff) ? (val + 1) : val;
66	  case VX_OM_STENCIL_OP_DECR:      return (val > 0) ? (val - 1) : val;
67	  case VX_OM_STENCIL_OP_INVERT:    return ~val;
68	  case VX_OM_STENCIL_OP_INCR_WRAP: return (val + 1) & 0xff;
69	  case VX_OM_STENCIL_OP_DECR_WRAP: return (val - 1) & 0xff;
70	  case VX_OM_STENCIL_OP_KEEP:      default: return val;
71	  }
72	}
73	
74	static inline __attribute__((always_inline)) uint32_t DoLogicOp(uint32_t op, uint32_t src, uint32_t dst) {
75	  switch (op) {
76	  case VX_OM_LOGIC_OP_CLEAR:        return 0;
77	  case VX_OM_LOGIC_OP_AND:          return src & dst;
78	  case VX_OM_LOGIC_OP_AND_REVERSE:  return src & ~dst;
79	  case VX_OM_LOGIC_OP_COPY:         return src;
80	  case VX_OM_LOGIC_OP_AND_INVERTED: return ~src & dst;
81	  case VX_OM_LOGIC_OP_NOOP:         return dst;
82	  case VX_OM_LOGIC_OP_XOR:          return src ^ dst;
83	  case VX_OM_LOGIC_OP_OR:           return src | dst;
84	  case VX_OM_LOGIC_OP_NOR:          return ~(src | dst);
85	  case VX_OM_LOGIC_OP_EQUIV:        return ~(src ^ dst);
86	  case VX_OM_LOGIC_OP_INVERT:       return ~dst;
87	  case VX_OM_LOGIC_OP_OR_REVERSE:   return src | ~dst;
88	  case VX_OM_LOGIC_OP_COPY_INVERTED:return ~src;
89	  case VX_OM_LOGIC_OP_OR_INVERTED:  return ~src | dst;
90	  case VX_OM_LOGIC_OP_NAND:         return ~(src & dst);
91	  case VX_OM_LOGIC_OP_SET:          default: return 0xffffffff;
92	  }
93	}
