95	static inline __attribute__((always_inline)) ColorARGB DoBlendFunc(uint32_t func, ColorARGB src, ColorARGB dst, ColorARGB cst) {
96	  switch (func) {
97	  case VX_OM_BLEND_FUNC_ZERO:               return ColorARGB(0, 0, 0, 0);
98	  case VX_OM_BLEND_FUNC_ONE:                return ColorARGB(0xff, 0xff, 0xff, 0xff);
99	  case VX_OM_BLEND_FUNC_SRC_RGB:            return src;
100	  case VX_OM_BLEND_FUNC_ONE_MINUS_SRC_RGB:  return ColorARGB(0xff - src.a, 0xff - src.r, 0xff - src.g, 0xff - src.b);
101	  case VX_OM_BLEND_FUNC_DST_RGB:            return dst;
102	  case VX_OM_BLEND_FUNC_ONE_MINUS_DST_RGB:  return ColorARGB(0xff - dst.a, 0xff - dst.r, 0xff - dst.g, 0xff - dst.b);
103	  case VX_OM_BLEND_FUNC_SRC_A:              return ColorARGB(src.a, src.a, src.a, src.a);
104	  case VX_OM_BLEND_FUNC_ONE_MINUS_SRC_A:    return ColorARGB(0xff - src.a, 0xff - src.a, 0xff - src.a, 0xff - src.a);
105	  case VX_OM_BLEND_FUNC_DST_A:              return ColorARGB(dst.a, dst.a, dst.a, dst.a);
106	  case VX_OM_BLEND_FUNC_ONE_MINUS_DST_A:    return ColorARGB(0xff - dst.a, 0xff - dst.a, 0xff - dst.a, 0xff - dst.a);
107	  case VX_OM_BLEND_FUNC_CONST_RGB:          return cst;
108	  case VX_OM_BLEND_FUNC_ONE_MINUS_CONST_RGB:return ColorARGB(0xff - cst.a, 0xff - cst.r, 0xff - cst.g, 0xff - cst.b);
109	  case VX_OM_BLEND_FUNC_CONST_A:            return ColorARGB(cst.a, cst.a, cst.a, cst.a);
110	  case VX_OM_BLEND_FUNC_ONE_MINUS_CONST_A:  return ColorARGB(0xff - cst.a, 0xff - cst.a, 0xff - cst.a, 0xff - cst.a);
111	  case VX_OM_BLEND_FUNC_ALPHA_SAT: {
112	    int factor = sw_min<int>(src.a, 0xff - dst.a);
113	    return ColorARGB(0xff, factor, factor, factor);
114	  }
115	  default:                                  return ColorARGB(0, 0, 0, 0);
116	  }
117	}
118	
119	static inline __attribute__((always_inline)) ColorARGB DoBlendMode(uint32_t mode, uint32_t logic_op,
120	                                    ColorARGB src, ColorARGB dst, ColorARGB s, ColorARGB d) {
121	  switch (mode) {
122	  case VX_OM_BLEND_MODE_ADD:
123	    return ColorARGB(
124	      Div255(sw_min<int>(src.a * s.a + dst.a * d.a + 0x80, 0xFF00)),
125	      Div255(sw_min<int>(src.r * s.r + dst.r * d.r + 0x80, 0xFF00)),
126	      Div255(sw_min<int>(src.g * s.g + dst.g * d.g + 0x80, 0xFF00)),
127	      Div255(sw_min<int>(src.b * s.b + dst.b * d.b + 0x80, 0xFF00)));
128	  case VX_OM_BLEND_MODE_SUB:
129	    return ColorARGB(
130	      Div255(sw_max<int>(src.a * s.a - dst.a * d.a + 0x80, 0x0)),
131	      Div255(sw_max<int>(src.r * s.r - dst.r * d.r + 0x80, 0x0)),
132	      Div255(sw_max<int>(src.g * s.g - dst.g * d.g + 0x80, 0x0)),
133	      Div255(sw_max<int>(src.b * s.b - dst.b * d.b + 0x80, 0x0)));
134	  case VX_OM_BLEND_MODE_REV_SUB:
135	    return ColorARGB(
136	      Div255(sw_max<int>(dst.a * d.a - src.a * s.a + 0x80, 0x0)),
137	      Div255(sw_max<int>(dst.r * d.r - src.r * s.r + 0x80, 0x0)),
138	      Div255(sw_max<int>(dst.g * d.g - src.g * s.g + 0x80, 0x0)),
139	      Div255(sw_max<int>(dst.b * d.b - src.b * s.b + 0x80, 0x0)));
140	  case VX_OM_BLEND_MODE_MIN:
141	    return ColorARGB(sw_min(src.a, dst.a), sw_min(src.r, dst.r), sw_min(src.g, dst.g), sw_min(src.b, dst.b));
142	  case VX_OM_BLEND_MODE_MAX:
143	    return ColorARGB(sw_max(src.a, dst.a), sw_max(src.r, dst.r), sw_max(src.g, dst.g), sw_max(src.b, dst.b));
144	  case VX_OM_BLEND_MODE_LOGICOP:
145	    return ColorARGB(DoLogicOp(logic_op, src.value, dst.value));
146	  default:
147	    return src;
148	  }
149	}
