151	// ── Resolved output-merger state (host fills from the same values it programs
152	//    into the OM DCRs; resolve_om_state() derives the enable flags / masks the
153	//    same way the fixed-function OM does) ─────────────────────────────────────
154	struct om_state_t {
155	  // depth/stencil (index 0 = front face, 1 = back face)
156	  uint32_t depth_func;
157	  uint32_t stencil_func[2], stencil_zpass[2], stencil_zfail[2], stencil_fail[2];
158	  uint32_t stencil_ref[2], stencil_mask[2], stencil_writemask[2];
159	  uint32_t depth_writemask;            // 0/1
160	  // blend
161	  uint32_t blend_mode_rgb, blend_mode_a;
162	  uint32_t blend_src_rgb, blend_src_a, blend_dst_rgb, blend_dst_a;
163	  uint32_t blend_const, logic_op;
164	  // framebuffer (device byte addresses)
165	  uint64_t zbuf_base, cbuf_base;
166	  uint32_t zbuf_pitch, cbuf_pitch;
167	  uint32_t cbuf_writemask4;            // 4-bit per-channel enable (as programmed)
168	  uint32_t color_format;               // VX_OM_COLOR_FORMAT_* (0 = A8R8G8B8)
169	  uint32_t depth_format;               // VX_OM_DEPTH_FORMAT_* (0 = D24S8)
170	  // resolved by resolve_om_state()
171	  uint32_t depth_enabled, stencil_enabled[2], blend_enabled;
172	  uint32_t cbuf_writemask;             // expanded 32-bit byte mask
173	  uint32_t color_read, color_write;
174	};
175	
176	// Derive the enable flags + expanded color mask exactly as the FF unit does.
177	// Call host-side after filling the raw
178	// fields, before handing om_state_t to the device.
179	static inline __attribute__((always_inline)) void resolve_om_state(om_state_t& s) {
180	  s.depth_enabled = !((s.depth_func == VX_OM_DEPTH_FUNC_ALWAYS) && !(s.depth_writemask & 0x1));
181	  for (int f = 0; f < 2; ++f)
182	    s.stencil_enabled[f] = !((s.stencil_func[f]  == VX_OM_DEPTH_FUNC_ALWAYS)
183	                          && (s.stencil_zpass[f] == VX_OM_STENCIL_OP_KEEP)
184	                          && (s.stencil_zfail[f] == VX_OM_STENCIL_OP_KEEP));
185	  s.blend_enabled = !((s.blend_mode_rgb == VX_OM_BLEND_MODE_ADD)
186	                   && (s.blend_mode_a   == VX_OM_BLEND_MODE_ADD)
187	                   && (s.blend_src_rgb  == VX_OM_BLEND_FUNC_ONE)
188	                   && (s.blend_src_a    == VX_OM_BLEND_FUNC_ONE)
189	                   && (s.blend_dst_rgb  == VX_OM_BLEND_FUNC_ZERO)
190	                   && (s.blend_dst_a    == VX_OM_BLEND_FUNC_ZERO));
191	  uint32_t m4 = s.cbuf_writemask4 & 0xf;
192	  s.cbuf_writemask = (((m4 >> 0) & 1) * 0x000000ff) | (((m4 >> 1) & 1) * 0x0000ff00)
193	                   | (((m4 >> 2) & 1) * 0x00ff0000) | (((m4 >> 3) & 1) * 0xff000000);
194	  s.color_read  = (m4 != 0xf);
195	  s.color_write = (m4 != 0x0);
196	}
197	
198	// ── attachment-format encode/decode (SW OM only) ─────────────────────────────
199	// The FF vx_om4 unit writes only A8R8G8B8 colour + packed D24S8 depth; every
200	// other colour/depth format is handled here in the software output-merger. The
201	// OM works internally in ARGB8888; colour is decoded from / encoded to the bound
202	// format on read/write (sRGB is blended in linear space per the Vulkan spec).
203	
204	static inline __attribute__((always_inline)) uint32_t Linear8ToSrgb(uint32_t c) {
205	  static const uint8_t kLinToSrgb[256] = {
206	      0, 13, 22, 28, 34, 38, 42, 46, 50, 53, 56, 59, 61, 64, 66, 69,
207	     71, 73, 75, 77, 79, 81, 83, 85, 86, 88, 90, 92, 93, 95, 96, 98,
208	     99,101,102,104,105,106,108,109,110,112,113,114,115,117,118,119,
209	    120,121,122,124,125,126,127,128,129,130,131,132,133,134,135,136,
210	    137,138,139,140,141,142,143,144,145,146,147,148,148,149,150,151,
211	    152,153,154,155,155,156,157,158,159,159,160,161,162,163,163,164,
212	    165,166,167,167,168,169,170,170,171,172,173,173,174,175,175,176,
213	    177,178,178,179,180,180,181,182,182,183,184,185,185,186,187,187,
214	    188,189,189,190,190,191,192,192,193,194,194,195,196,196,197,197,
215	    198,199,199,200,200,201,202,202,203,203,204,205,205,206,206,207,
216	    208,208,209,209,210,210,211,212,212,213,213,214,214,215,215,216,
217	    216,217,218,218,219,219,220,220,221,221,222,222,223,223,224,224,
218	    225,226,226,227,227,228,228,229,229,230,230,231,231,232,232,233,
219	    233,234,234,235,235,236,236,237,237,238,238,238,239,239,240,240,
220	    241,241,242,242,243,243,244,244,245,245,246,246,246,247,247,248,
221	    248,249,249,250,250,251,251,251,252,252,253,253,254,254,255,255};
222	  return kLinToSrgb[c & 0xff];
223	}
