225	static inline __attribute__((always_inline)) uint32_t om_color_bpp(uint32_t fmt) {
226	  switch (fmt) {
227	  case VX_OM_COLOR_FORMAT_R8:  return 1;
228	  case VX_OM_COLOR_FORMAT_RG8: return 2;
229	  default:                     return 4;   // A8R8G8B8 / SRGB8A8
230	  }
231	}
232	static inline __attribute__((always_inline)) uint32_t om_depth_bpp(uint32_t fmt) {
233	  switch (fmt) {
234	  case VX_OM_DEPTH_FORMAT_S8:  return 1;
235	  case VX_OM_DEPTH_FORMAT_D16: return 2;
236	  default:                     return 4;   // D24S8 / D32F
237	  }
238	}
239	
240	// Read/write `bpp` bytes at a byte address (LSU-style, no wider access than the
241	// attachment's texel so R8/RG8 packed rows are addressed exactly).
242	static inline __attribute__((always_inline)) uint32_t om_load(uintptr_t a, uint32_t bpp) {
243	  if (bpp == 4) return *reinterpret_cast<volatile uint32_t*>(a);
244	  if (bpp == 2) return *reinterpret_cast<volatile uint16_t*>(a);
245	  return *reinterpret_cast<volatile uint8_t*>(a);
246	}
247	static inline __attribute__((always_inline)) void om_store(uintptr_t a, uint32_t bpp, uint32_t v) {
248	  if (bpp == 4)      *reinterpret_cast<volatile uint32_t*>(a) = v;
249	  else if (bpp == 2) *reinterpret_cast<volatile uint16_t*>(a) = (uint16_t)v;
250	  else               *reinterpret_cast<volatile uint8_t*>(a)  = (uint8_t)v;
251	}
252	
253	// Decode a stored colour texel → ARGB8888 working colour (sRGB → linear so the
254	// blend runs in linear space).
255	static inline __attribute__((always_inline)) uint32_t om_decode_color(uint32_t fmt, uint32_t raw) {
256	  switch (fmt) {
257	  case VX_OM_COLOR_FORMAT_SRGB8A8: {
258	    uint32_t r = gfx_tex::SrgbToLinear8((raw >> 16) & 0xff);
259	    uint32_t g = gfx_tex::SrgbToLinear8((raw >> 8) & 0xff);
260	    uint32_t b = gfx_tex::SrgbToLinear8(raw & 0xff);
261	    return (raw & 0xff000000u) | (r << 16) | (g << 8) | b;   // alpha linear
262	  }
263	  case VX_OM_COLOR_FORMAT_R8:  return 0xff000000u | ((raw & 0xff) << 16);
264	  case VX_OM_COLOR_FORMAT_RG8: return 0xff000000u | ((raw & 0xff) << 16) | (((raw >> 8) & 0xff) << 8);
265	  default:                     return raw;    // A8R8G8B8
266	  }
267	}
268	
269	// Encode an ARGB8888 working colour → stored texel (linear → sRGB on write).
270	static inline __attribute__((always_inline)) uint32_t om_encode_color(uint32_t fmt, uint32_t argb) {
271	  switch (fmt) {
272	  case VX_OM_COLOR_FORMAT_SRGB8A8: {
273	    uint32_t r = Linear8ToSrgb((argb >> 16) & 0xff);
274	    uint32_t g = Linear8ToSrgb((argb >> 8) & 0xff);
275	    uint32_t b = Linear8ToSrgb(argb & 0xff);
276	    return (argb & 0xff000000u) | (r << 16) | (g << 8) | b;
277	  }
278	  case VX_OM_COLOR_FORMAT_R8:  return (argb >> 16) & 0xff;
279	  case VX_OM_COLOR_FORMAT_RG8: return ((argb >> 16) & 0xff) | (((argb >> 8) & 0xff) << 8);
280	  default:                     return argb;
281	  }
282	}
