284	// Per-format depth geometry: comparison mask, stencil presence, and the bit
285	// offset of the stencil field within the packed depth/stencil word.
286	struct om_depth_desc { uint32_t dmask; uint32_t sshift; bool has_depth; bool has_stencil; };
287	static inline __attribute__((always_inline)) om_depth_desc om_depth_geom(uint32_t fmt) {
288	  switch (fmt) {
289	  case VX_OM_DEPTH_FORMAT_D16:  return { 0xffffu,     0,  true,  false };
290	  case VX_OM_DEPTH_FORMAT_D32F: return { 0xffffffffu, 0,  true,  false };  // float bits, monotonic for [0,1]
291	  case VX_OM_DEPTH_FORMAT_S8:   return { 0u,          0,  false, true  };
292	  default:                      return { OM_DEPTH_MASK, VX_OM_DEPTH_BITS, true, true }; // D24S8
293	  }
294	}
295	
296	// ── Per-fragment software ops (device + host) ────────────────────────────────
297	
298	// Depth/stencil test. `ds_val` is the packed
299	// {stencil:depth} word at the pixel in the bound depth format; writes the merged
300	// word to *ds_result and returns whether the fragment passes the combined
301	// stencil+depth test. D32F compares the raw float bits (monotonic over [0,1]).
302	static inline __attribute__((always_inline)) bool ds_test(const om_state_t& s, uint32_t face, uint32_t depth,
303	                           uint32_t ds_val, uint32_t* ds_result) {
304	  const int f = face ? 1 : 0;
305	  om_depth_desc dd = om_depth_geom(s.depth_format);
306	  uint32_t depth_val   = ds_val & dd.dmask;
307	  uint32_t stencil_val = dd.has_stencil ? ((ds_val >> dd.sshift) & 0xff) : 0;
308	  uint32_t depth_ref   = depth & dd.dmask;
309	
310	  uint32_t sref = s.stencil_ref[f], smask = s.stencil_mask[f];
311	  uint32_t sref_m = sref & smask, sval_m = stencil_val & smask;
312	
313	  uint32_t stencil_op;
314	  bool passed = dd.has_stencil ? DoCompare(s.stencil_func[f], sref_m, sval_m) : true;
315	  if (passed) {
316	    passed = dd.has_depth ? DoCompare(s.depth_func, depth_ref, depth_val) : true;
317	    stencil_op = passed ? s.stencil_zpass[f] : s.stencil_zfail[f];
318	  } else {
319	    stencil_op = s.stencil_fail[f];
320	  }
321	  uint32_t stencil_result = dd.has_stencil ? DoStencilOp(stencil_op, sref, stencil_val) : 0;
322	  *ds_result = (stencil_result << dd.sshift) | depth_ref;
323	  return passed;
324	}
325	
326	// Blend.
327	static inline __attribute__((always_inline)) uint32_t blend(const om_state_t& s, uint32_t src_color, uint32_t dst_color) {
328	  ColorARGB src(src_color), dst(dst_color), cst(s.blend_const);
329	  ColorARGB s_rgb = DoBlendFunc(s.blend_src_rgb, src, dst, cst);
330	  ColorARGB s_a   = DoBlendFunc(s.blend_src_a,   src, dst, cst);
331	  ColorARGB d_rgb = DoBlendFunc(s.blend_dst_rgb, src, dst, cst);
332	  ColorARGB d_a   = DoBlendFunc(s.blend_dst_a,   src, dst, cst);
333	  ColorARGB rgb = DoBlendMode(s.blend_mode_rgb, s.logic_op, src, dst, s_rgb, d_rgb);
334	  ColorARGB a   = DoBlendMode(s.blend_mode_a,   s.logic_op, src, dst, s_a,   d_a);
335	  ColorARGB result(a.a, rgb.r, rgb.g, rgb.b);
336	  return result.value;
337	}
338	
339	// One output-merge read-modify-write at explicit depth/color byte addresses
340	// (host + device): the LSU-based equivalent of one OM lane. Reads dst depth/
341	// stencil + color, runs the depth/stencil test + blend, applies the write-masks,
342	// and writes back — the single body shared by the single-sample om_fragment and
343	// the per-sample MSAA path (om_fragment_msaa), so both are bit-identical to the
344	// FF OM unit. Returns whether the depth/stencil test passed.
345	//
346	// Non-atomic RMW: correct when each (pixel, sample) is touched once. Per-sample
347	// ordering for overlapping fragments is the determinism open item, handled by
348	// the SW path's tile serialization.
349	static inline __attribute__((always_inline)) bool om_sample_rmw(
350	    const om_state_t& s, uintptr_t z_addr, uintptr_t c_addr,
351	    uint32_t face, uint32_t src_color, uint32_t src_depth) {
352	  const int f = face ? 1 : 0;
353	  om_depth_desc dd = om_depth_geom(s.depth_format);
354	  uint32_t dbpp = om_depth_bpp(s.depth_format);
355	  uint32_t cbpp = om_color_bpp(s.color_format);
356	  bool ds_active = s.depth_enabled || s.stencil_enabled[f];
357	  bool need_c_read = s.color_write && (s.color_read || s.blend_enabled);
358	
359	  uint32_t dst_ds    = ds_active   ? om_load(z_addr, dbpp) : 0;
360	  uint32_t dst_raw   = need_c_read ? om_load(c_addr, cbpp) : 0;
361	  uint32_t dst_color = om_decode_color(s.color_format, dst_raw);   // decode → blend in linear
362	
363	  uint32_t merged = 0;
364	  bool ds_pass = !ds_active || ds_test(s, face, src_depth, dst_ds, &merged);
365	  uint32_t blended = (s.blend_enabled && ds_pass) ? blend(s, src_color, dst_color) : src_color;
366	
367	  uint32_t stencil_wm = s.stencil_writemask[f];
368	  uint32_t ds_wm = ((s.depth_enabled && ds_pass && s.depth_writemask && dd.has_depth) ? dd.dmask : 0u)
369	                 | ((s.stencil_enabled[f] && dd.has_stencil) ? (stencil_wm << dd.sshift) : 0u);
370	  if (ds_wm)
371	    om_store(z_addr, dbpp, (dst_ds & ~ds_wm) | (merged & ds_wm));
372	
373	  if (s.color_write && ds_pass) {
374	    uint32_t out_argb = (dst_color & ~s.cbuf_writemask) | (blended & s.cbuf_writemask);
375	    om_store(c_addr, cbpp, om_encode_color(s.color_format, out_argb));
376	  }
377	  return ds_pass;
378	}
379	
380	// ── MSAA storage + resolve ───────────────────────────────────────────────────
381	// Per-sample surfaces are sample-interleaved within a pixel: a pixel's S samples
382	// are contiguous, so a row is W*S texels and the per-sample column offset is
383	// (x*S + sample). cbuf_pitch / zbuf_pitch in om_state_t already carry the
384	// MSAA row stride (= W*S*4). Keeping samples contiguous makes resolve a unit-
385	// stride gather.
386	static inline __attribute__((always_inline)) uintptr_t msaa_color_addr(
387	    const om_state_t& s, uint32_t samples, uint32_t x, uint32_t y, uint32_t sample) {
388	  return (uintptr_t)(s.cbuf_base + (uint64_t)y * s.cbuf_pitch + (uint64_t)(x * samples + sample) * om_color_bpp(s.color_format));
389	}
390	static inline __attribute__((always_inline)) uintptr_t msaa_depth_addr(
391	    const om_state_t& s, uint32_t samples, uint32_t x, uint32_t y, uint32_t sample) {
392	  return (uintptr_t)(s.zbuf_base + (uint64_t)y * s.zbuf_pitch + (uint64_t)(x * samples + sample) * om_depth_bpp(s.depth_format));
393	}
394	
395	// Box resolve of one pixel's S color samples → a single ARGB8888 value
396	// (per-channel average, round-to-nearest). Depth is not averaged (use sample 0
397	// or the multisample z-buffer directly), matching standard MSAA color resolve.
398	static inline __attribute__((always_inline)) uint32_t msaa_resolve_color(
399	    const om_state_t& s, uint32_t samples, uint32_t x, uint32_t y) {
400	  // Read each sample at its native texel width and decode to linear ARGB before
401	  // averaging, then re-encode — so R8/RG8 packing and sRGB gamma resolve
402	  // correctly. A8R8G8B8 decode/encode are identity (byte-identical fast path).
403	  uint32_t bpp = om_color_bpp(s.color_format);
404	  uint32_t acc[4] = {0, 0, 0, 0};
405	  for (uint32_t k = 0; k < samples; ++k) {
406	    uint32_t raw = om_load(msaa_color_addr(s, samples, x, y, k), bpp);
407	    uint32_t c   = om_decode_color(s.color_format, raw);
408	    acc[0] +=  c        & 0xff;
409	    acc[1] += (c >>  8) & 0xff;
410	    acc[2] += (c >> 16) & 0xff;
411	    acc[3] += (c >> 24) & 0xff;
412	  }
413	  uint32_t half = samples >> 1;
414	  uint32_t out = 0;
415	  for (uint32_t ch = 0; ch < 4; ++ch) {
416	    out |= (((acc[ch] + half) / samples) & 0xff) << (ch * 8);
417	  }
418	  return om_encode_color(s.color_format, out);
419	}
420	
421	// ── SW texture sampler: on-device fallback for vx_tex4 ───────────────────────
422	// Reads texels straight from resident texture memory (no FF tcache) using the
423	// shared gfx_frag_tex.h math, so the result matches the FF unit (and the cocogfx
424	// oracle) bit-for-bit — it IS the same compute_request/apply_filter code. Works
425	// on host too (base_addr a plain pointer), so the FF model + a host parity test
426	// can exercise it as the SW oracle.
427	static inline __attribute__((always_inline)) uint32_t tex_load_texel(uint64_t addr, uint32_t stride) {
428	  if (stride == 4) return *(const uint32_t*)(uintptr_t)addr;
429	  if (stride == 2) return *(const uint16_t*)(uintptr_t)addr;
430	  return *(const uint8_t*)(uintptr_t)addr;
431	}
432	
433	// Extended per-LOD sample (SW-path only): any format above the FF set and/or
434	// a CLAMP_TO_BORDER wrap. Reuses tex_compute_request for the tap offsets (base 0
435	// → offset*stride), decodes each tap to ARGB8888 via TexDecodeExtended, applies
436	// the border colour to out-of-range taps, and filters in the 8-bit ARGB working
437	// space (point → tap 0, bilinear → TexFilterLinear as A8R8G8B8).
438	static inline __attribute__((always_inline)) uint32_t tex_sample_ext_lod(
439	    uint64_t base_addr, uint32_t logdim, uint32_t format, uint32_t filter,
440	    uint32_t wrap, int32_t u, int32_t v, uint32_t lod,
441	    uint32_t width, uint32_t height, uint32_t border) {
442	  gfx_tex::TexelRequest req =
443	    gfx_tex::tex_compute_request(0, logdim, format, filter, wrap, u, v, lod, width, height);
444	  uint32_t stride = req.stride;
445	  // per-LOD dims for the border range check (match tex_compute_request).
446	  uint32_t log_width  = (uint32_t)gfx_tex::tex_imax((int32_t)(logdim & 0xffff) - (int32_t)lod, 0);
447	  uint32_t log_height = (uint32_t)gfx_tex::tex_imax((int32_t)(logdim >> 16) - (int32_t)lod, 0);
448	  uint32_t w = width  ? (uint32_t)gfx_tex::tex_imax((int32_t)(width  >> lod), 1) : (1u << log_width);
449	  uint32_t h = height ? (uint32_t)gfx_tex::tex_imax((int32_t)(height >> lod), 1) : (1u << log_height);
450	  uint32_t bmask = gfx_tex::TexBorderMask(u, v, w, h, log_width, log_height,
451	                                          wrap & 0xffff, wrap >> 16, req.filter);
452	  if (req.filter == VX_TEX_FILTER_BILINEAR) {
453	    uint32_t argb[4];
454	    for (uint32_t i = 0; i < 4; ++i)
455	      argb[i] = ((bmask >> i) & 1u) ? border
456	              : gfx_tex::TexDecodeArgb8(format, (const void*)(uintptr_t)(base_addr + req.addr[i]), stride);
457	    // filter as A8R8G8B8 (taps already linear 8-bit ARGB).
458	    return gfx_tex::TexFilterLinear(VX_TEX_FORMAT_A8R8G8B8, argb[0], argb[1], argb[2], argb[3],
459	                                    req.alpha, req.beta);
460	  }
461	  if (bmask & 1u) return border;
462	  return gfx_tex::TexDecodeArgb8(format, (const void*)(uintptr_t)(base_addr + req.addr[0]), stride);
463	}
464	
465	// One LOD's sample (POINT or BILINEAR). `base_addr` is the mip's base for `lod`
466	// (mip_base + mip_off); `logdim` is mip 0's {log_h<<16|log_w}; u/v are
467	// TEX_FXD_FRAC fixed-point. Caller does trilinear by blending two LODs. The
468	// FF-format + non-border case keeps the exact bit-identical shared path; the
469	// extended-format or border case routes to tex_sample_ext_lod.
470	static inline __attribute__((always_inline)) uint32_t tex_sample_sw_lod(
471	    uint64_t base_addr, uint32_t logdim, uint32_t format, uint32_t filter,
472	    uint32_t wrap, int32_t u, int32_t v, uint32_t lod,
473	    uint32_t width = 0, uint32_t height = 0, uint32_t border = 0) {
474	  bool has_border = ((wrap & 0xffff) == VX_TEX_WRAP_BORDER) || ((wrap >> 16) == VX_TEX_WRAP_BORDER);
475	  if (!gfx_tex::TexIsFFFormat(format) || has_border)
476	    return tex_sample_ext_lod(base_addr, logdim, format, filter, wrap, u, v, lod,
477	                              width, height, border);
478	  gfx_tex::TexelRequest req =
479	    gfx_tex::tex_compute_request(base_addr, logdim, format, filter, wrap, u, v, lod,
480	                                 width, height);
481	  uint32_t texels[4] = {0, 0, 0, 0};
482	  uint32_t taps = (req.filter == VX_TEX_FILTER_BILINEAR) ? 4u : 1u;
483	  for (uint32_t i = 0; i < taps; ++i)
484	    texels[i] = tex_load_texel(req.addr[i], req.stride);
485	  return gfx_tex::tex_apply_filter(req, texels);
486	}
487	
488	// Resident texture state for one stage (the SW mirror of the texture DCR state):
489	// mip base,
490	// per-LOD mip offsets, dims, format, full filter (incl the mip-linear bit), and
491	// wrap. The device fragment kernel fills this from the bound texture's resident
492	// descriptor; the host FF model fills it from the texture DCRs — both then drive
493	// tex_sample_sw, so the SW path matches vx_tex4 bit-for-bit.
494	struct TexState {
495	  uint64_t base;                          // mip 0 base (TEX_ADDR << 6)
496	  uint32_t mip_off[VX_TEX_LOD_MAX + 1];   // per-LOD byte offset from base
497	  uint32_t logdim;                        // {log_h << 16 | log_w} of mip 0
498	  uint32_t format;                        // VX_TEX_FORMAT_*
499	  uint32_t filter;                        // mag/min (bit 0) | mip-linear (bit 1)
500	  uint32_t wrap;                          // {wrap_v << 16 | wrap_u}
501	  uint32_t width;                         // mip-0 integer width  (0 => POT via logdim)
502	  uint32_t height;                        // mip-0 integer height (0 => POT via logdim)
503	  uint32_t border;                        // ARGB8888 border colour (WRAP_BORDER)
504	  uint32_t layer_stride;                  // bytes per array layer / cube face (0 => single 2D)
505	};
506	
507	// Full vx_tex4 SW fallback: a complete (u, v, lod) sample including the
508	// trilinear mip blend. Mirrors the FF texture sampler exactly (same per-LOD tap
509	// math via tex_sample_sw_lod, same two-mip TexLodLerp), so it is bit-identical
510	// to the FF unit. `lod` is fixed-point when the mip filter is linear.
511	static inline __attribute__((always_inline)) uint32_t tex_sample_sw_layer(
512	    const TexState& s, int32_t u, int32_t v, uint32_t lod, uint32_t layer) {
513	  // mag/min selects the per-LOD tap pattern; the mip-linear bit is consumed here.
514	  uint32_t tap_filter = s.filter & TEX_FILTER_MAGMIN_MASK;
515	  uint64_t lbase = s.base + (uint64_t)layer * s.layer_stride;   // array/cube slice
516	  if (s.filter & VX_TEX_FILTER_MIP_LINEAR) {
517	    uint32_t li   = lod >> VX_TEX_LOD_FRAC_BITS;
518	    uint32_t lj   = (li + 1 < (uint32_t)VX_TEX_LOD_MAX) ? li + 1 : (uint32_t)VX_TEX_LOD_MAX;
519	    uint32_t frac = lod & ((1u << VX_TEX_LOD_FRAC_BITS) - 1);
520	    uint32_t c0 = tex_sample_sw_lod(lbase + s.mip_off[li], s.logdim, s.format,
521	                                    tap_filter, s.wrap, u, v, li, s.width, s.height, s.border);
522	    uint32_t c1 = tex_sample_sw_lod(lbase + s.mip_off[lj], s.logdim, s.format,
523	                                    tap_filter, s.wrap, u, v, lj, s.width, s.height, s.border);
524	    return gfx_tex::TexLodLerp(c0, c1, frac);
525	  }
526	  return tex_sample_sw_lod(lbase + s.mip_off[lod], s.logdim, s.format,
527	                           tap_filter, s.wrap, u, v, lod, s.width, s.height, s.border);
528	}
529	
530	static inline __attribute__((always_inline)) uint32_t tex_sample_sw(
531	    const TexState& s, int32_t u, int32_t v, uint32_t lod) {
532	  return tex_sample_sw_layer(s, u, v, lod, 0);
533	}
534	
535	// 2D-array view: integer layer index selects the slice at layer*layer_stride.
536	static inline __attribute__((always_inline)) uint32_t tex_sample_sw_array(
537	    const TexState& s, int32_t u, int32_t v, uint32_t layer, uint32_t lod) {
538	  return tex_sample_sw_layer(s, u, v, lod, layer);
539	}
540	
541	// Cube view: pick the face from the major axis of the (sc,tc,rc) direction and
542	// project to the face's [0,1] uv, then sample that face's slice (face index is the
543	// layer). Face order matches Vulkan/GL cube layers: +X,-X,+Y,-Y,+Z,-Z = 0..5.
544	// Coordinates are floats (the FS supplies the interpolated direction vector).
545	static inline __attribute__((always_inline)) uint32_t tex_sample_sw_cube(
546	    const TexState& s, float sc, float tc, float rc, uint32_t lod) {
547	  float asx = sc < 0 ? -sc : sc, asy = tc < 0 ? -tc : tc, asz = rc < 0 ? -rc : rc;
548	  uint32_t face; float ma, uc, vc;
549	  if (asx >= asy && asx >= asz) {
550	    ma = asx; face = (sc >= 0) ? 0u : 1u; uc = (sc >= 0) ? -rc : rc; vc = -tc;
551	  } else if (asy >= asz) {
552	    ma = asy; face = (tc >= 0) ? 2u : 3u; uc = sc; vc = (tc >= 0) ? rc : -rc;
553	  } else {
554	    ma = asz; face = (rc >= 0) ? 4u : 5u; uc = (rc >= 0) ? sc : -sc; vc = -tc;
555	  }
556	  float inv = (ma != 0.0f) ? (0.5f / ma) : 0.0f;
557	  float fu = uc * inv + 0.5f, fv = vc * inv + 0.5f;
558	  const int32_t ONE = 1 << TEX_FXD_FRAC;
559	  int32_t u = (int32_t)(fu * (float)ONE), v = (int32_t)(fv * (float)ONE);
560	  return tex_sample_sw_layer(s, u, v, lod, face);
561	}
562	
563	// libgfx_sw build contract: om_fragment's full depth+blend+ROP merge (below)
564	// inflates the fragment kernel past the Vortex divergence pass's default 100-BB
565	// guard. If the guard trips, the pass silently skips StructurizeCFG + split/join
566	// and miscompiles the kernel (unselectable uniform markers, unmasked divergent
567	// control flow). The fix is a *build* flag (-mllvm -vortex-divergence-max-bbs),
568	// not a source change, so it can't be enforced in the header alone — encapsulate
569	// it in sw/gfx/libgfx_sw.mk, which raises the guard AND defines
570	// GFX_SW_DIVERGENCE_OK. Fail loudly here if a DEVICE kernel pulls in om_fragment
571	// without it, rather than miscompiling silently. (Host builds — the FF model and
572	// the gfx_msaa parity test — compile the merge normally; there is no divergence
573	// pass on the host, so no flag is required there.)
574	#if defined(__VORTEX__) && !defined(GFX_SW_DIVERGENCE_OK)
575	#error "gfx_sw.h om_fragment needs the divergence-bbs build flag: include sw/gfx/libgfx_sw.mk and add $(LIBGFX_SW_VX_CFLAGS) to the kernel VX_CFLAGS"
576	#endif
577	// Software output-merger for one fragment: the LSU-based
578	// equivalent of vx_om(). Reads dst depth/stencil + color from resident memory,
579	// runs the test + blend, applies the write-masks, and writes back — mirroring
580	// the FF OM compute+write sequence exactly. Caller supplies the same
581	// (x, y, face, src_color, src_depth) it would pass to vx_om.
582	//
583	// NOTE: like a single OM lane this is a non-atomic read-modify-write; it is
584	// correct when each pixel is touched once (no concurrent same-pixel fragments).
585	// Per-pixel ordering/atomicity for overlapping fragments is the determinism
586	// open item, handled with the SW path's tile
587	// serialization / MSAA work.
588	//
589	// TOOLCHAIN NOTE: inline this whole merge into the fragment kernel
590	// (always_inline) and build the kernel with -mllvm -vortex-divergence-max-bbs=N
591	// (N large enough to cover the kernel). The full depth+blend+ROP merge inflates
592	// the kernel past the Vortex divergence pass's default 100-BB guard; if the
593	// guard trips, the pass skips StructurizeCFG + split/join, leaving the kernel's
594	// uniform OM-state reads as unselectable llvm.riscv.vx.uniform markers and its
595	// divergent control flow unmasked. With the guard raised the kernel is processed
596	// normally and the merge is bit-exact vs the FF OM unit (validated, all configs).
597	static inline __attribute__((always_inline)) void om_fragment(const om_state_t& s, uint32_t x, uint32_t y,
598	                               uint32_t face, uint32_t src_color, uint32_t src_depth) {
599	  uintptr_t z_addr = (uintptr_t)(s.zbuf_base + (uint64_t)y * s.zbuf_pitch + (uint64_t)x * om_depth_bpp(s.depth_format));
600	  uintptr_t c_addr = (uintptr_t)(s.cbuf_base + (uint64_t)y * s.cbuf_pitch + (uint64_t)x * om_color_bpp(s.color_format));
601	  om_sample_rmw(s, z_addr, c_addr, face, src_color, src_depth);
602	}
603	
604	// Per-sample MSAA output-merge for one fragment: run the OM merge at each
605	// covered sample's storage slot. `samples` is the sample count (1/2/4),
606	// `sample_mask` is the per-pixel coverage from rast_sample_mask (bit k = sample
607	// k covered). Each covered sample gets its own depth-test + blend + ROP against
608	// its own per-sample depth/color slot — equivalent to S independent OM lanes for
609	// this pixel. `src_color`/`src_depth` are the shaded fragment values (shared
610	// across the pixel's samples; per-sample attribute interpolation can refine
611	// src_depth per sample later — centroid shading keeps a single color).
612	static inline __attribute__((always_inline)) void om_fragment_msaa(
613	    const om_state_t& s, uint32_t samples, uint32_t x, uint32_t y, uint32_t face,
614	    uint32_t sample_mask, uint32_t src_color, uint32_t src_depth) {
615	  for (uint32_t k = 0; k < samples; ++k) {
616	    if (!((sample_mask >> k) & 1u)) continue;
617	    om_sample_rmw(s, msaa_depth_addr(s, samples, x, y, k),
618	                  msaa_color_addr(s, samples, x, y, k), face, src_color, src_depth);
619	  }
620	}
621	
622	// ── Multiple render targets ──────────────────────────────────────────────────
623	// The depth/stencil test is shared across all colour attachments (single depth
624	// buffer), so MRT keeps om_state_t as the depth/stencil + shared framebuffer
625	// geometry and adds a per-attachment colour descriptor. Vulkan requires
626	// maxColorAttachments >= 4.
627	#ifndef VX_OM_MAX_RT
628	#define VX_OM_MAX_RT 4
629	#endif
630	
631	// One colour attachment's blend/write configuration (mirror of the per-RT slice
632	// of the OM blend DCRs). Depth/stencil is not here — it is shared in om_state_t.
633	struct om_color_t {
634	  uint64_t cbuf_base;                  // attachment byte base
635	  uint32_t cbuf_pitch;                 // attachment row stride (bytes)
636	  uint32_t blend_mode_rgb, blend_mode_a;
637	  uint32_t blend_src_rgb, blend_src_a, blend_dst_rgb, blend_dst_a;
638	  uint32_t blend_const, logic_op;
639	  uint32_t cbuf_writemask4;            // 4-bit per-channel enable (as programmed)
640	  uint32_t color_format;               // VX_OM_COLOR_FORMAT_* (0 = A8R8G8B8)
641	  // resolved by resolve_om_color()
642	  uint32_t blend_enabled;
643	  uint32_t cbuf_writemask;             // expanded 32-bit byte mask
644	  uint32_t color_read, color_write;
645	};
646	
647	// Derive a colour attachment's enable flags + expanded mask exactly as
648	// resolve_om_state() does for the single-RT fields.
649	static inline __attribute__((always_inline)) void resolve_om_color(om_color_t& c) {
650	  c.blend_enabled = !((c.blend_mode_rgb == VX_OM_BLEND_MODE_ADD)
651	                   && (c.blend_mode_a   == VX_OM_BLEND_MODE_ADD)
652	                   && (c.blend_src_rgb  == VX_OM_BLEND_FUNC_ONE)
653	                   && (c.blend_src_a    == VX_OM_BLEND_FUNC_ONE)
654	                   && (c.blend_dst_rgb  == VX_OM_BLEND_FUNC_ZERO)
655	                   && (c.blend_dst_a    == VX_OM_BLEND_FUNC_ZERO));
656	  uint32_t m4 = c.cbuf_writemask4 & 0xf;
657	  c.cbuf_writemask = (((m4 >> 0) & 1) * 0x000000ff) | (((m4 >> 1) & 1) * 0x0000ff00)
658	                   | (((m4 >> 2) & 1) * 0x00ff0000) | (((m4 >> 3) & 1) * 0xff000000);
659	  c.color_read  = (m4 != 0xf);
660	  c.color_write = (m4 != 0x0);
661	}
662	
663	// Blend for an explicit per-attachment colour descriptor (the MRT twin of
664	// blend(); both go through the same free DoBlendFunc/DoBlendMode ops so an
665	// attachment's result matches the single-RT path bit-for-bit).
666	static inline __attribute__((always_inline)) uint32_t blend_rt(const om_color_t& c, uint32_t src_color, uint32_t dst_color) {
667	  ColorARGB src(src_color), dst(dst_color), cst(c.blend_const);
668	  ColorARGB s_rgb = DoBlendFunc(c.blend_src_rgb, src, dst, cst);
669	  ColorARGB s_a   = DoBlendFunc(c.blend_src_a,   src, dst, cst);
670	  ColorARGB d_rgb = DoBlendFunc(c.blend_dst_rgb, src, dst, cst);
671	  ColorARGB d_a   = DoBlendFunc(c.blend_dst_a,   src, dst, cst);
672	  ColorARGB rgb = DoBlendMode(c.blend_mode_rgb, c.logic_op, src, dst, s_rgb, d_rgb);
673	  ColorARGB a   = DoBlendMode(c.blend_mode_a,   c.logic_op, src, dst, s_a,   d_a);
674	  return ColorARGB(a.a, rgb.r, rgb.g, rgb.b).value;
675	}
676	
677	// Software output-merger for one fragment writing N colour attachments: the
678	// depth/stencil test + write-back runs ONCE against the shared z-buffer, then
679	// each attachment k does its own blend + colour write of src_colors[k] at its
680	// own base/pitch (matching a real MRT OM: one depth op, N colour ops). Bit-
681	// identical to N single-RT om_fragment calls that share one depth result.
682	static inline __attribute__((always_inline)) void om_fragment_mrt(
683	    const om_state_t& s, const om_color_t* colors, uint32_t num_color,
684	    uint32_t x, uint32_t y, uint32_t face,
685	    const uint32_t* src_colors, uint32_t src_depth) {
686	  const int f = face ? 1 : 0;
687	  // clamp the attachment count to the hardware bound so a stale/short
688	  // colors[] or an over-large num_color can never read past colors[]/src_colors[].
689	  if (num_color > VX_OM_MAX_RT) num_color = VX_OM_MAX_RT;
690	  bool ds_active = s.depth_enabled || s.stencil_enabled[f];
691	  om_depth_desc dd = om_depth_geom(s.depth_format);
692	  uint32_t dbpp = om_depth_bpp(s.depth_format);
693	  uintptr_t z_addr = (uintptr_t)(s.zbuf_base + (uint64_t)y * s.zbuf_pitch + (uint64_t)x * dbpp);
694	
695	  uint32_t dst_ds = ds_active ? om_load(z_addr, dbpp) : 0;
696	  uint32_t merged = 0;
697	  bool ds_pass = !ds_active || ds_test(s, face, src_depth, dst_ds, &merged);
698	
699	  uint32_t stencil_wm = s.stencil_writemask[f];
700	  uint32_t ds_wm = ((s.depth_enabled && ds_pass && s.depth_writemask && dd.has_depth) ? dd.dmask : 0u)
701	                 | ((s.stencil_enabled[f] && dd.has_stencil) ? (stencil_wm << dd.sshift) : 0u);
702	  if (ds_wm)
703	    om_store(z_addr, dbpp, (dst_ds & ~ds_wm) | (merged & ds_wm));
704	
705	  if (!ds_pass)
706	    return;
707	
708	  for (uint32_t k = 0; k < num_color; ++k) {
709	    const om_color_t& c = colors[k];
710	    if (!c.color_write) continue;
711	    uint32_t cbpp = om_color_bpp(c.color_format);
712	    uintptr_t c_addr = (uintptr_t)(c.cbuf_base + (uint64_t)y * c.cbuf_pitch + (uint64_t)x * cbpp);
713	    bool need_c_read = c.color_read || c.blend_enabled;
714	    uint32_t dst_raw = need_c_read ? om_load(c_addr, cbpp) : 0;
715	    uint32_t dst_color = om_decode_color(c.color_format, dst_raw);
716	    uint32_t blended = c.blend_enabled ? blend_rt(c, src_colors[k], dst_color) : src_colors[k];
717	    uint32_t out_argb = (dst_color & ~c.cbuf_writemask) | (blended & c.cbuf_writemask);
718	    om_store(c_addr, cbpp, om_encode_color(c.color_format, out_argb));
719	  }
720	}
721	
722	} // namespace gfx_sw
