51	TexelRequest TextureSampler::compute_request(uint32_t stage, int32_t u, int32_t v, uint32_t lod) const {
52	  auto mip_off  = dcrs_.read(stage, VX_DCR_TEX_MIPOFF(lod));
53	  auto mip_base = uint64_t(dcrs_.read(stage, VX_DCR_TEX_ADDR)) << 6;
54	  auto logdim   = dcrs_.read(stage, VX_DCR_TEX_LOGDIM);
55	  auto format   = dcrs_.read(stage, VX_DCR_TEX_FORMAT);
56	  // mag/min filter is the low bit; the mip-filter bit (trilinear) lives above
57	  // it and is handled by the caller, so mask it off for per-LOD tap selection.
58	  auto filter   = dcrs_.read(stage, VX_DCR_TEX_FILTER) & TEX_FILTER_MAGMIN_MASK;
59	  auto wrap     = dcrs_.read(stage, VX_DCR_TEX_WRAP);
60	
61	  // The sampling math is shared with the on-device SW fallback (gfx_frag_tex.h).
62	  return gfx_tex::tex_compute_request(mip_base + mip_off, logdim, format,
63	                                      filter, wrap, u, v, lod);
64	}
65	
66	uint32_t TextureSampler::apply_filter(const TexelRequest& req, const uint32_t texels[4]) {
67	  return gfx_tex::tex_apply_filter(req, texels);
68	}
69	
70	uint32_t TextureSampler::read(uint32_t stage, int32_t u, int32_t v, uint32_t lod) const {
71	  auto sample_lod = [&](uint32_t l) -> uint32_t {
72	    auto req = this->compute_request(stage, u, v, l);
73	    uint32_t texels[4] = {0, 0, 0, 0};
74	    uint32_t count = (req.filter == VX_TEX_FILTER_BILINEAR) ? 4 : 1;
75	    mem_cb_(texels, req.addr, req.stride, count, cb_arg_);
76	    return apply_filter(req, texels);
77	  };
78	  // gfx_v2 §6.8 trilinear: `lod` is fixed-point — sample the two bracketing
79	  // mips and blend by the fractional part (lod1 clamped to VX_TEX_LOD_MAX).
80	  if (this->mip_linear(stage)) {
81	    uint32_t li   = lod >> VX_TEX_LOD_FRAC_BITS;
82	    uint32_t lj   = (li + 1 < (uint32_t)VX_TEX_LOD_MAX) ? li + 1 : (uint32_t)VX_TEX_LOD_MAX;
83	    uint32_t frac = lod & ((1u << VX_TEX_LOD_FRAC_BITS) - 1);
84	    return TexLodLerp(sample_lod(li), sample_lod(lj), frac);
85	  }
86	  return sample_lod(lod);
87	}
