119	void DepthTencil::configure(const OMDCRS& dcrs) {
120	  depth_func_          = dcrs.read(VX_DCR_OM_DEPTH_FUNC);
121	  bool depth_writemask = dcrs.read(VX_DCR_OM_DEPTH_WRITEMASK) & 0x1;
122	
123	  stencil_front_func_ = dcrs.read(VX_DCR_OM_STENCIL_FUNC) & 0xffff;
124	  stencil_front_zpass_= dcrs.read(VX_DCR_OM_STENCIL_ZPASS) & 0xffff;
125	  stencil_front_zfail_= dcrs.read(VX_DCR_OM_STENCIL_ZFAIL) & 0xffff;
126	  stencil_front_fail_ = dcrs.read(VX_DCR_OM_STENCIL_FAIL) & 0xffff;
127	  stencil_front_ref_  = dcrs.read(VX_DCR_OM_STENCIL_REF) & 0xffff;
128	  stencil_front_mask_ = dcrs.read(VX_DCR_OM_STENCIL_MASK) & 0xffff;
129	
130	  stencil_back_func_  = dcrs.read(VX_DCR_OM_STENCIL_FUNC) >> 16;
131	  stencil_back_zpass_ = dcrs.read(VX_DCR_OM_STENCIL_ZPASS) >> 16;
132	  stencil_back_zfail_ = dcrs.read(VX_DCR_OM_STENCIL_ZFAIL) >> 16;
133	  stencil_back_fail_  = dcrs.read(VX_DCR_OM_STENCIL_FAIL) >> 16;    
134	  stencil_back_ref_   = dcrs.read(VX_DCR_OM_STENCIL_REF) >> 16;
135	  stencil_back_mask_  = dcrs.read(VX_DCR_OM_STENCIL_MASK) >> 16;
136	
137	  depth_enabled_ = !((depth_func_ == VX_OM_DEPTH_FUNC_ALWAYS) && !depth_writemask);
138	  
139	  stencil_front_enabled_ = !((stencil_front_func_  == VX_OM_DEPTH_FUNC_ALWAYS) 
140	                          && (stencil_front_zpass_ == VX_OM_STENCIL_OP_KEEP)
141	                          && (stencil_front_zfail_ == VX_OM_STENCIL_OP_KEEP));
142	  
143	  stencil_back_enabled_ = !((stencil_back_func_  == VX_OM_DEPTH_FUNC_ALWAYS) 
144	                          && (stencil_back_zpass_ == VX_OM_STENCIL_OP_KEEP)
145	                          && (stencil_back_zfail_ == VX_OM_STENCIL_OP_KEEP));
146	}
147	
148	bool DepthTencil::test(uint32_t is_backface, 
149	                       uint32_t depth, 
150	                       uint32_t depthstencil_val, 
151	                       uint32_t* depthstencil_result) const {
152	  auto depth_val   = depthstencil_val & OM_DEPTH_MASK;
153	  auto stencil_val = depthstencil_val >> VX_OM_DEPTH_BITS;
154	  auto depth_ref   = depth & OM_DEPTH_MASK;
155	    
156	  auto stencil_func = is_backface ? stencil_back_func_ : stencil_front_func_;    
157	  auto stencil_ref  = is_backface ? stencil_back_ref_  : stencil_front_ref_;    
158	  auto stencil_mask = is_backface ? stencil_back_mask_ : stencil_front_mask_;
159	  
160	  auto stencil_ref_m = stencil_ref & stencil_mask;
161	  auto stencil_val_m = stencil_val & stencil_mask;
162	
163	  uint32_t stencil_op;
164	
165	  auto passed = DoCompare(stencil_func, stencil_ref_m, stencil_val_m);
166	  if (passed) {
167	    passed = DoCompare(depth_func_, depth_ref, depth_val);
168	    if (passed) {
169	      stencil_op = is_backface ? stencil_back_zpass_ : stencil_front_zpass_;              
170	    } else {
171	      stencil_op = is_backface ? stencil_back_zfail_ : stencil_front_zfail_;
172	    } 
173	  } else {
174	    stencil_op = is_backface ? stencil_back_fail_ : stencil_front_fail_;
175	  }
176	  
177	  auto stencil_result = DoStencilOp(stencil_op, stencil_ref, stencil_val);
178	  *depthstencil_result = (stencil_result << VX_OM_DEPTH_BITS) | depth_ref;
179	  return passed;
180	}
