187	void Blender::configure(const OMDCRS& dcrs) {
188	  blend_mode_rgb_ = dcrs.read(VX_DCR_OM_BLEND_MODE) & 0xffff;
189	  blend_mode_a_   = dcrs.read(VX_DCR_OM_BLEND_MODE) >> 16;
190	  blend_src_rgb_  = (dcrs.read(VX_DCR_OM_BLEND_FUNC) >>  0) & 0xff;
191	  blend_src_a_    = (dcrs.read(VX_DCR_OM_BLEND_FUNC) >>  8) & 0xff;
192	  blend_dst_rgb_  = (dcrs.read(VX_DCR_OM_BLEND_FUNC) >> 16) & 0xff;
193	  blend_dst_a_    = (dcrs.read(VX_DCR_OM_BLEND_FUNC) >> 24) & 0xff;
194	  blend_const_    = dcrs.read(VX_DCR_OM_BLEND_CONST);
195	  logic_op_       = dcrs.read(VX_DCR_OM_LOGIC_OP);  
196	
197	  enabled_        = !((blend_mode_rgb_ == VX_OM_BLEND_MODE_ADD)
198	                   && (blend_mode_a_   == VX_OM_BLEND_MODE_ADD) 
199	                   && (blend_src_rgb_  == VX_OM_BLEND_FUNC_ONE) 
200	                   && (blend_src_a_    == VX_OM_BLEND_FUNC_ONE) 
201	                   && (blend_dst_rgb_  == VX_OM_BLEND_FUNC_ZERO) 
202	                   && (blend_dst_a_    == VX_OM_BLEND_FUNC_ZERO));
203	}
204	
205	uint32_t Blender::blend(uint32_t srcColor, uint32_t dstColor) const {
206	  ColorARGB src(srcColor);
207	  ColorARGB dst(dstColor);
208	  ColorARGB cst(blend_const_);
209	
210	  auto s_rgb = DoBlendFunc(blend_src_rgb_, src, dst, cst);
211	  auto s_a   = DoBlendFunc(blend_src_a_, src, dst, cst);
212	  auto d_rgb = DoBlendFunc(blend_dst_rgb_, src, dst, cst);
213	  auto d_a   = DoBlendFunc(blend_dst_a_, src, dst, cst);
214	  auto rgb   = DoBlendMode(blend_mode_rgb_, logic_op_, src, dst, s_rgb, d_rgb);
215	  auto a     = DoBlendMode(blend_mode_a_, logic_op_, src, dst, s_a, d_a);
216	  ColorARGB result(a.a, rgb.r, rgb.g, rgb.b);
217	
218	  return result.value;
219	}
