240	
241	void Rasterizer::renderPrimitive(uint32_t x,
242	                                 uint32_t y,
243	                                 uint32_t pid,
244	                                 vec3e_t edges[3]) const {
245	  // The coverage walk is the single source of truth shared with the device SW
246	  // fallback (gfx_frag_rast.h, §7); forward the FF model's ShaderCB as the emit sink.
247	  gfx_rast::RastConfig cfg{
248	    tile_logsize_,
249	    scissor_left_, scissor_top_, scissor_right_, scissor_bottom_
250	  };
251	  gfx_rast::rast_walk_primitive(cfg, x, y, pid, edges,
252	    [&](uint32_t pos_mask, vortex::graphics::vec3e_t* bcoords, uint32_t prim_id) {
253	      shader_cb_(pos_mask, bcoords, prim_id, cb_arg_);
254	    });
255	}
