2	
3	// gfx_v2 fused setup -> binning front end — device kernel stages.
4	//
5	// Defines the two kernel entries that produce RASTER's gfx-v1 buffers: setup_k
6	// (clip + triangle setup -> dense primbuf + bbox + P) and binning_k (bin-sort
7	// over the dense tile grid -> tilebuf). Include from a test's kernel.cpp; the
8	// test adds its own fragment/consumer kernel. Device-only (pulls vx_spawn2.h).
9	
10	#include <vx_spawn2.h>
11	#include <gfx_frontend_abi.h>   // pipe_arg_t, PIPE_STAGE_*, PIPE_PRIM_*, setup types
12	#include <gfx_setup.h>          // gfx_setup::{clip_near, setup_triangle}
13	
14	// Coarse bin granularity the front end bins at (= VX_CFG_RASTER_BIN_LOG_SIZE,
15	// supplied as a -D in the kernel build; fallback for standalone include).
16	#ifndef VX_CFG_RASTER_BIN_LOG_SIZE
17	#define VX_CFG_RASTER_BIN_LOG_SIZE 7
18	#endif
19	#ifndef PIPE_BIN_LOG
20	#define PIPE_BIN_LOG   VX_CFG_RASTER_BIN_LOG_SIZE
21	#endif
22	
23	namespace gfx_pipe {
24	
25	using gfx_setup::rast_prim_t;
26	using gfx_setup::setup_triangle;
27	using gfx_setup::clip_near;
28	using vortex::graphics::rast_bin_header_t;
29	
30	static inline uint32_t pipe_umin(uint32_t a, uint32_t b) { return a < b ? a : b; }
31	
32	static inline void pipe_bin_range(const setup_bbox_t& p, int& bL, int& bR, int& bT, int& bB) {
33	  bL = p.bbL >> PIPE_BIN_LOG; bR = (p.bbR - 1) >> PIPE_BIN_LOG;
34	  bT = p.bbT >> PIPE_BIN_LOG; bB = (p.bbB - 1) >> PIPE_BIN_LOG;
35	}
36	
37	// Clip + setup for one triangle, kept out-of-line so the FP math does not bloat
38	// the entry (the merged 9-stage function otherwise overruns the uniform pass).
39	static uint32_t __attribute__((noinline))
40	pipe_clip_and_setup(const setup_vertex_t* v, int W, int H, uint32_t cull_mode,
41	                    const setup_viewport_t* vp,
42	                    rast_prim_t* prim_out, setup_bbox_t* bbox_out) {
43	  clip_tri_t sub[SETUP_MAX_SUB];
44	  int ns = clip_near(v[0], v[1], v[2], sub);
45	  uint32_t kept = 0;
46	  for (int s = 0; s < ns; ++s) {
47	    rast_prim_t prim{};
48	    setup_bbox_t bb{};
49	    if (setup_triangle(sub[s].v[0], sub[s].v[1], sub[s].v[2], W, H,
50	                       SETUP_NEAR, SETUP_FAR, prim, bb, cull_mode, vp)) {
51	      prim_out[kept] = prim;
52	      bbox_out[kept] = bb;
53	      ++kept;
54	    }
55	  }
56	  return kept;
57	}
58	
59	} // namespace gfx_pipe
60	
61	// ---- vertex assembly: resident VS records -> setup_vertex_t[] (no readback) --
62	// Routes each VS-output record into the front end's vertex form: slot 0 is the
63	// clip-space position, slots 1.. are generic varyings (16 bytes each), mapped
64	// by component count (2 -> texcoord, 3/4 -> colour) the gfx-v1 way. One
65	// thread/vertex; grid-strided so any launch geometry covers num_verts.
66	__kernel void expand_k(expand_arg_t* __UNIFORM__ arg) {
67	  auto recs = reinterpret_cast<const uint8_t*>(arg->vsrec_addr);
68	  auto out  = reinterpret_cast<setup_vertex_t*>(arg->verts_addr);
69	  const uint32_t n      = arg->num_verts;
70	  const uint32_t stride = arg->vstride;
71	  const uint32_t nv     = arg->num_varyings;
72	  uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
73	  uint32_t gstride = gridDim.x * blockDim.x;
74	  for (uint32_t i = gid; i < n; i += gstride) {
75	    const uint8_t* rec = recs + (size_t)i * stride;
76	    const float*   pos = reinterpret_cast<const float*>(rec);
77	    setup_vertex_t v;
78	    v.pos[0] = pos[0]; v.pos[1] = pos[1]; v.pos[2] = pos[2]; v.pos[3] = pos[3];
79	    v.color[0] = 1.0f; v.color[1] = 1.0f; v.color[2] = 1.0f; v.color[3] = 1.0f;
80	    v.texcoord[0] = 0.0f; v.texcoord[1] = 0.0f;
81	    for (uint32_t vi = 0; vi < nv; ++vi) {
82	      const float* a = reinterpret_cast<const float*>(rec + 16u * (1u + vi));
83	      uint32_t nc = arg->varying_comps[vi];
84	      if (nc == 2) {
85	        v.texcoord[0] = a[0]; v.texcoord[1] = a[1];
86	      } else if (nc >= 3) {
87	        v.color[0] = a[0]; v.color[1] = a[1];
88	        v.color[2] = a[2]; v.color[3] = nc >= 4 ? a[3] : 1.0f;
89	      }
90	    }
91	    out[i] = v;
92	  }
93	}
94	
95	// ---- setup front end: clip + setup -> dense primbuf + bbox + P (meta[0]) ----
96	__kernel void setup_k(pipe_arg_t* __UNIFORM__ arg) {
97	  using namespace gfx_pipe;
98	  auto verts     = reinterpret_cast<setup_vertex_t*>(arg->verts_addr);
99	  auto keep      = reinterpret_cast<uint32_t*>(arg->keep_addr);
100	  auto offset    = reinterpret_cast<uint32_t*>(arg->offset_addr);
101	  auto tsum      = reinterpret_cast<uint32_t*>(arg->tsum_addr);
102	  auto prim      = reinterpret_cast<rast_prim_t*>(arg->prim_addr);
103	  auto bbox      = reinterpret_cast<setup_bbox_t*>(arg->bbox_addr);
104	  auto meta      = reinterpret_cast<uint32_t*>(arg->meta_addr);
105	
106	  const uint32_t ntri = arg->num_tris;
107	  const int      W = (int)arg->width;
108	  const int      H = (int)arg->height;
109	  const uint32_t tid = threadIdx.x;
110	  const uint32_t T   = blockDim.x;
111	
112	  // App viewport transform, or the default full-framebuffer y-down mapping when
113	  // unset (all four zero — what the standalone setup tests, which zero-init the
114	  // arg block, feed). Passing &vp / nullptr selects the branch inside setup.
115	  setup_viewport_t vp;
116	  const bool have_vp = (arg->vp_sx != 0.0f) || (arg->vp_tx != 0.0f)
117	                    || (arg->vp_sy != 0.0f) || (arg->vp_ty != 0.0f);
118	  vp.sx = arg->vp_sx; vp.tx = arg->vp_tx;
119	  vp.sy = arg->vp_sy; vp.ty = arg->vp_ty;
120	  const setup_viewport_t* vpp = have_vp ? &vp : nullptr;
121	
122	  switch (arg->stage) {
123	
124	  case PIPE_STAGE_SETUP: {
125	    // Count survivors only. The dense scatter (EMIT) recomputes clip+setup and
126	    // writes each rast_prim_t straight to its compacted slot, so the 120-byte
127	    // record is never staged to a scratch buffer and read back — clip+setup is
128	    // a pure function of the (unchanged) input vertices, so the count here and
129	    // the per-triangle output in EMIT match exactly. Halves primbuf write
130	    // traffic and removes the slot_prim/slot_bbox scratch entirely.
131	    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
132	    uint32_t gstride = gridDim.x * blockDim.x;
133	    for (uint32_t t = gid; t < ntri; t += gstride) {
134	      rast_prim_t pr[SETUP_MAX_SUB];
135	      setup_bbox_t bb[SETUP_MAX_SUB];
136	      keep[t] = pipe_clip_and_setup(&verts[3 * t], W, H, arg->cull_mode, vpp, pr, bb);
137	    }
138	  } break;
139	
140	  case PIPE_STAGE_SCAN: {
141	    uint32_t chunk = (ntri + T - 1) / T;
142	    uint32_t lo = pipe_umin(tid * chunk, ntri), hi = pipe_umin(lo + chunk, ntri);
143	    { uint32_t s = 0; for (uint32_t i = lo; i < hi; ++i) s += keep[i]; tsum[tid] = s; }
144	    __syncthreads();
145	    if (tid == 0) {
146	      uint32_t acc = 0;
147	      for (uint32_t t = 0; t < T; ++t) { uint32_t v = tsum[t]; tsum[t] = acc; acc += v; }
148	      meta[0] = acc; offset[ntri] = acc;
149	    }
150	    __syncthreads();
151	    { uint32_t acc = tsum[tid]; for (uint32_t i = lo; i < hi; ++i) { offset[i] = acc; acc += keep[i]; } }
152	  } break;
153	
154	  case PIPE_STAGE_EMIT: {
155	    // Recompute clip+setup and scatter directly into the dense primbuf at the
156	    // scanned offset — no round-trip through a per-triangle scratch slot. kept
157	    // here equals keep[t] from SETUP (same pure function, same inputs).
158	    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
159	    uint32_t gstride = gridDim.x * blockDim.x;
160	    for (uint32_t t = gid; t < ntri; t += gstride) {
161	      rast_prim_t pr[SETUP_MAX_SUB];
162	      setup_bbox_t bb[SETUP_MAX_SUB];
163	      uint32_t kept = pipe_clip_and_setup(&verts[3 * t], W, H, arg->cull_mode, vpp, pr, bb);
164	      uint32_t w = offset[t];
165	      for (uint32_t s = 0; s < kept; ++s) {
166	        prim[w] = pr[s];
167	        bbox[w] = bb[s];
168	        ++w;
169	      }
170	    }
171	  } break;
172	
173	  }
174	}
175	
176	// ---- binning back end: bin-sort dense bbox[] (P=meta[0]) -> dense tilebuf ----
177	__kernel void binning_k(pipe_arg_t* __UNIFORM__ arg) {
178	  using namespace gfx_pipe;
179	  auto bbox      = reinterpret_cast<setup_bbox_t*>(arg->bbox_addr);
180	  auto bcount    = reinterpret_cast<uint32_t*>(arg->bcount_addr);
181	  auto boffset   = reinterpret_cast<uint32_t*>(arg->boffset_addr);
182	  auto keys      = reinterpret_cast<uint32_t*>(arg->keys_addr);
183	  auto btsum     = reinterpret_cast<uint32_t*>(arg->btsum_addr);
184	  auto thist     = reinterpret_cast<uint32_t*>(arg->thist_addr);
185	  auto bincount  = reinterpret_cast<uint32_t*>(arg->bincount_addr);
186	  auto binbase   = reinterpret_cast<uint32_t*>(arg->binbase_addr);
187	  auto tilebuf   = reinterpret_cast<uint8_t*>(arg->tilebuf_addr);
188	  auto meta      = reinterpret_cast<uint32_t*>(arg->meta_addr);
189	
190	  const uint32_t tid = threadIdx.x;
191	  const uint32_t T   = blockDim.x;
192	  const uint32_t B   = arg->num_bins;     // dense tile grid sized to the render target
193	
194	  switch (arg->stage) {
195	
196	  case PIPE_STAGE_BCOUNT: {
197	    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
198	    uint32_t gstride = gridDim.x * blockDim.x;
199	    uint32_t P = meta[0];
200	    for (uint32_t i = gid; i < P; i += gstride) {
201	      int bL, bR, bT, bB; pipe_bin_range(bbox[i], bL, bR, bT, bB);
202	      bcount[i] = (uint32_t)((bR - bL + 1) * (bB - bT + 1));
203	    }
204	  } break;
205	
206	  case PIPE_STAGE_BSCAN: {
207	    uint32_t P = meta[0];
208	    uint32_t chunk = (P + T - 1) / T;
209	    uint32_t lo = pipe_umin(tid * chunk, P), hi = pipe_umin(lo + chunk, P);
210	    { uint32_t s = 0; for (uint32_t i = lo; i < hi; ++i) s += bcount[i]; btsum[tid] = s; }
211	    __syncthreads();
212	    if (tid == 0) {
213	      uint32_t acc = 0;
214	      for (uint32_t t = 0; t < T; ++t) { uint32_t v = btsum[t]; btsum[t] = acc; acc += v; }
215	      meta[1] = acc; boffset[P] = acc;
216	    }
217	    __syncthreads();
218	    { uint32_t acc = btsum[tid]; for (uint32_t i = lo; i < hi; ++i) { boffset[i] = acc; acc += bcount[i]; } }
219	  } break;
220	
221	  case PIPE_STAGE_BEMIT: {
222	    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
223	    uint32_t gstride = gridDim.x * blockDim.x;
224	    uint32_t P = meta[0];
225	    for (uint32_t i = gid; i < P; i += gstride) {
226	      int bL, bR, bT, bB; pipe_bin_range(bbox[i], bL, bR, bT, bB);
227	      uint32_t w = boffset[i];
228	      for (int by = bT; by <= bB; ++by)
229	        for (int bx = bL; bx <= bR; ++bx)
230	          keys[w++] = ((uint32_t)(by * arg->bin_cols + bx) << PIPE_PRIM_BITS) | i;
231	    }
232	  } break;
233	
234	  case PIPE_STAGE_BHIST: {
235	    uint32_t lo = blockIdx.x * arg->bin_stripe, hi = pipe_umin(lo + arg->bin_stripe, B);
236	    uint32_t K = meta[1];
237	    uint32_t kchunk = (K + T - 1) / T;
238	    uint32_t klo = pipe_umin(tid * kchunk, K), khi = pipe_umin(klo + kchunk, K);
239	    for (uint32_t b = lo; b < hi; ++b) thist[tid * B + b] = 0;
240	    __syncthreads();
241	    for (uint32_t k = klo; k < khi; ++k) { uint32_t b = keys[k] >> PIPE_PRIM_BITS; if (b >= lo && b < hi) thist[tid * B + b]++; }
242	    __syncthreads();
243	    for (uint32_t b = lo + tid; b < hi; b += T) { uint32_t s = 0; for (uint32_t t = 0; t < T; ++t) s += thist[t * B + b]; bincount[b] = s; }
244	  } break;
245	
246	  case PIPE_STAGE_BBASE: {
247	    // Dense bin grid: one rast_bin_header_t per bin (empty bins get
248	    // pids_count=0 and RASTER skips them), so the bin count is B =
249	    // bin_cols*bin_rows. pids_offset is the absolute index into the sorted_pids
250	    // array that follows the header block. Cooperative exclusive
251	    // prefix-scan of bincount[] across the CTA's T threads (mirrors BSCAN),
252	    // replacing the single-lane O(B) loop so a large bin grid parallelises.
253	    uint32_t chunk = (B + T - 1) / T;
254	    uint32_t lo = pipe_umin(tid * chunk, B), hi = pipe_umin(lo + chunk, B);
255	    { uint32_t s = 0; for (uint32_t b = lo; b < hi; ++b) s += bincount[b]; btsum[tid] = s; }
256	    __syncthreads();
257	    if (tid == 0) {
258	      uint32_t acc = 0;
259	      for (uint32_t t = 0; t < T; ++t) { uint32_t v = btsum[t]; btsum[t] = acc; acc += v; }
260	    }
261	    __syncthreads();
262	    auto hdr = reinterpret_cast<rast_bin_header_t*>(tilebuf);
263	    uint32_t nb_local = 0;
264	    { uint32_t acc = btsum[tid];
265	      for (uint32_t b = lo; b < hi; ++b) {
266	        hdr[b].bin_x       = (uint16_t)(b % arg->bin_cols);
267	        hdr[b].bin_y       = (uint16_t)(b / arg->bin_cols);
268	        hdr[b].pids_offset = acc;
269	        hdr[b].pids_count  = bincount[b];
270	        binbase[b]         = acc;
271	        if (bincount[b]) ++nb_local;
272	        acc += bincount[b];
273	      }
274	    }
275	    __syncthreads();
276	    btsum[tid] = nb_local;   // offsets consumed; reuse btsum for the nb reduction
277	    __syncthreads();
278	    if (tid == 0) {
279	      uint32_t nb = 0;
280	      for (uint32_t t = 0; t < T; ++t) nb += btsum[t];
281	      meta[2] = nb;  // non-empty bin count (informational)
282	    }
283	  } break;
284	
285	  case PIPE_STAGE_BSCATTER: {
286	    uint32_t lo = blockIdx.x * arg->bin_stripe, hi = pipe_umin(lo + arg->bin_stripe, B);
287	    uint32_t K = meta[1];
288	    auto pids = reinterpret_cast<uint32_t*>(tilebuf + B * sizeof(rast_bin_header_t));
289	    uint32_t kchunk = (K + T - 1) / T;
290	    uint32_t klo = pipe_umin(tid * kchunk, K), khi = pipe_umin(klo + kchunk, K);
291	    for (uint32_t b = lo + tid; b < hi; b += T) { uint32_t run = binbase[b]; for (uint32_t t = 0; t < T; ++t) { uint32_t c = thist[t * B + b]; thist[t * B + b] = run; run += c; } }
292	    __syncthreads();
293	    for (uint32_t k = klo; k < khi; ++k) {
294	      uint32_t key = keys[k], b = key >> PIPE_PRIM_BITS;
295	      if (b >= lo && b < hi) pids[thist[tid * B + b]++] = key & PIPE_PRIM_MASK;
296	    }
297	  } break;
298	
299	  }
300	}
