72	  cocogfx::ColorARGB out_color[4];
73	  for (int i = 0; i < 4; ++i) {
74	    z[i] = FloatA(0.0f); r[i] = FloatA(1.0f); g[i] = FloatA(1.0f);
75	    b[i] = FloatA(1.0f); a[i] = FloatA(1.0f);
76	  }
77	  auto prim_ptr = reinterpret_cast<rast_prim_t*>(arg->prim_addr);
78	
79	  // RASTER dispatch v2 (push): straight-line FS, payload already in the window.
80	  frag_payload_t p;
81	  vx_frag_load(p);
82	  uint32_t pos_mask = p.pos_mask;
83	  uint32_t pid = p.pid;
84	  auto& attribs = prim_ptr[pid].attribs;
85	  auto& edges = prim_ptr[pid].edges;   // recompute edge values from these
86	  uint32_t qx = (pos_mask >> 4) & ((1u << (VX_RASTER_DIM_BITS - 1)) - 1);
87	  uint32_t qy = (pos_mask >> (4 + (VX_RASTER_DIM_BITS - 1))) & ((1u << (VX_RASTER_DIM_BITS - 1)) - 1);
