89	  if (arg->depth_enabled) { PLANE_Z(z); }
90	  // Perspective divide: colour planes carry a*(1/w) (see gfx_draw3d/kernel.cpp).
91	  // Recover a by dividing the interpolated a*(1/w) by the interpolated 1/w.
92	  if (arg->color_enabled) {
93	    FloatA w_i[4];
94	    INTERPOLATE(w_i, attribs.rhw);
95	    INTERPOLATE(r, attribs.r); INTERPOLATE(g, attribs.g);
96	    INTERPOLATE(b, attribs.b); INTERPOLATE(a, attribs.a);
97	    for (int i = 0; i < 4; ++i) {
98	      float iw = (w_i[i].data() != 0) ? (1.0f / static_cast<float>(w_i[i])) : 0.0f;
99	      r[i] = FloatA(static_cast<float>(r[i]) * iw); g[i] = FloatA(static_cast<float>(g[i]) * iw);
100	      b[i] = FloatA(static_cast<float>(b[i]) * iw); a[i] = FloatA(static_cast<float>(a[i]) * iw);
101	    }
102	  }
103	  TO_RGBA(out_color, r, g, b, a);
104	  OUTPUT_QUAD(pos_mask, 0, out_color, z);
